from collections import defaultdict
p = 1000000007

def inv(i):
	return pow(i, p - 2, p)
mat = []
matinv = []
numpows = 11
for i in range(numpows):
	row = [0] * numpows
	mat.append(row)
	matinv.append(row.copy())
	matinv[i][i] = 1
for i in range(numpows):
	mat[i][0] = 1
	mat[i][i] = i + 1
	for j in range(1, i):
		mat[i][j] = mat[i - 1][j] + mat[i - 1][j - 1]
for i in range(numpows):
	for j in range(i + 1):
		if (i + j) % 2 == 1:
			mat[i][j] = p - mat[i][j]
for i in range(numpows):
	pivnum = mat[i][i]
	for j in range(numpows):
		mat[i][j] = mat[i][j] * inv(pivnum) % p
		matinv[i][j] = matinv[i][j] * inv(pivnum) % p
	for j in range(i + 1, numpows):
		subnum = p - mat[j][i]
		for k in range(numpows):
			mat[j][k] = (mat[j][k] + subnum * mat[i][k]) % p
			matinv[j][k] = (matinv[j][k] + subnum * matinv[i][k]) % p
powsums = dict()

def sumpow(i, k):
	try:
		return powsums[i, k]
	except:
		try:
			powsums[i, k] = (powsums[i - 1, k] + pow(i, k, p)) % p
			return powsums[i, k]
		except:
			toret = 0
			for a in range(k + 1):
				toret = (toret + matinv[k][a] * pow(i, a + 1, p)) % p
			powsums[i, k] = toret
			return toret

def noreps(a):
	toret = []
	currval = -1
	for x in a:
		if x != currval:
			toret.append(x)
		currval = x
	return toret

def merge(a, b):
	bind = 0
	if len(b) == 0:
		return a
	left = -1
	right = len(a)
	while right - left > 1:
		mid = (left + right) // 2
		if a[mid] > b[0]:
			left = mid
		else:
			right = mid
	toret = a[:left]
	aind = left
	while aind < len(a) and bind < len(b):
		if a[aind] == b[bind]:
			toret.append(a[aind])
			aind += 1
			bind += 1
		elif a[aind] > b[bind]:
			toret.append(a[aind])
			aind += 1
		elif b[bind] > a[aind]:
			toret.append(b[bind])
			bind += 1
	while aind < len(a):
		toret.append(a[aind])
		aind += 1
	while bind < len(b):
		toret.append(b[bind])
		bind += 1
	return toret
t = int(input())
for _ in range(t):
	(n, k, m) = list(map(int, input().split(' ')))
	s = list(map(int, input().split(' ')))
	s.sort()
	s.reverse()
	s = s[:n]
	tosum = defaultdict(lambda : 0)
	tosum[m] = 1
	tosumkeys = [m]
	for x in s:
		adddict = defaultdict(lambda : 0)
		addkeys = []
		for y in tosumkeys:
			if y < x:
				break
			adddict[y // x] += tosum[y]
			addkeys.append(y // x)
		addkeys = noreps(addkeys)
		mult = pow(x, k, p)
		for y in addkeys:
			tosum[y] = (tosum[y] - adddict[y] * mult) % p
		tosumkeys = merge(tosumkeys, addkeys)
	toprint = 0
	for x in reversed(tosumkeys):
		toprint += sumpow(x, k) * tosum[x]
	print(toprint % p)
